import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 4

def design(feats):
    # Remove near-duplicates based on correlation
    corr_threshold = 0.6
    keep = []
    correlated = set()

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    for i in range(len(feats.ids)):
        if i in correlated:
            continue
        keep.append(i)
        # Find correlated features to exclude
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= corr_threshold:
                correlated.add(j)

    # Select features based on t-statistics and correlation filtering
    selected_indices = []
    for i in keep:
        try:
            t_stat = stats.ttest_ind(feats.x[feats.y==1,i], feats.x[feats.y==0,i]).statistic
            if abs(t_stat) > 3.5:
                selected_indices.append(i)
        except:
            continue

    if not selected_indices:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Sort by effect size (t-statistic)
    t_stats = []
    for i in selected_indices:
        try:
            t_stat = stats.ttest_ind(feats.x[feats.y==1,i], feats.x[feats.y==0,i]).statistic
            t_stats.append(abs(t_stat))
        except:
            t_stats.append(0)

    sorted_indices = [i for _, i in sorted(zip(t_stats, selected_indices), key=lambda x: x[0], reverse=True)]

    # Select top drivers
    drivers = tuple(feats.ids[i] for i in sorted_indices[:MAX_DRIVERS])

    # Use all selected features for regression
    columns = tuple(feats.ids[i] for i in sorted_indices)

    # Create interaction terms between top features
    products = []
    for i in range(min(3, len(sorted_indices))):
        for j in range(i+1, min(3, len(sorted_indices))):
            products.append((feats.ids[sorted_indices[i]], feats.ids[sorted_indices[j]]))

    # Weighted score using top features
    loadings = {}
    for i, idx in enumerate(sorted_indices[:3]):
        loadings[feats.ids[idx]] = 1.0 / (i + 1)

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

